#!/usr/bin/env bash
set -uo pipefail

# Test: boundary-check.sh emits AskUserQuestion guidance when blocking out-of-scope paths
# Generated by /qa on 2026-04-23
# Covers: .claude/hooks/boundary-check.sh stderr message contract + exit codes

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$SCRIPT_DIR/.claude/hooks/boundary-check.sh"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; }

if [ ! -x "$HOOK" ]; then
  echo "FATAL: hook not found or not executable at $HOOK" >&2
  exit 1
fi

echo "Testing: boundary-check.sh AskUserQuestion guidance"
echo ""

# --- Fixture: project dir + boundary file the hook expects ---
FIXTURE_PROJECT="$(mktemp -d)"
FIXTURE_MEMORY="$(mktemp -d)"
FIXTURE_REPO="$(mktemp -d)"
HASH=$(echo -n "$FIXTURE_PROJECT" | md5 2>/dev/null || echo -n "$FIXTURE_PROJECT" | md5sum 2>/dev/null | cut -d' ' -f1)
BOUNDARY_FILE="/tmp/egregore-boundary-${HASH}.json"
cat > "$BOUNDARY_FILE" <<EOF
{
  "project_dir": "$FIXTURE_PROJECT",
  "memory_dir": "$FIXTURE_MEMORY",
  "managed_repos": ["$FIXTURE_REPO"],
  "denied_paths": ["/tmp/egregore-other-instance"]
}
EOF
export CLAUDE_PROJECT_DIR="$FIXTURE_PROJECT"

cleanup() {
  rm -rf "$FIXTURE_PROJECT" "$FIXTURE_MEMORY" "$FIXTURE_REPO" "$BOUNDARY_FILE"
}
trap cleanup EXIT

run_hook() {
  # Pipes tool_input JSON to hook, returns "exit_code|stderr"
  local input="$1"
  local err rc
  err=$(echo "$input" | "$HOOK" 2>&1 >/dev/null)
  rc=$?
  printf '%s|%s' "$rc" "$err"
}

# --- 1. Read on out-of-scope path: blocks + AskUserQuestion guidance ---
OUT=$(run_hook '{"tool_name":"Read","tool_input":{"file_path":"/Users/someone/Downloads/report.txt"}}')
RC="${OUT%%|*}"
ERR="${OUT#*|}"

[ "$RC" = "2" ] && pass "Read out-of-scope exits 2" || fail "Read out-of-scope exit code" "expected 2, got $RC"
grep -q "AskUserQuestion" <<< "$ERR" && pass "Read block mentions AskUserQuestion" || fail "Read block missing AskUserQuestion directive" "stderr: $ERR"
grep -q "Paste contents inline" <<< "$ERR" && pass "Read block offers paste-inline option" || fail "Read block missing paste-inline option"
grep -q "for this session" <<< "$ERR" && pass "Read block offers session-allow option" || fail "Read block missing session-allow option"
grep -q "Always allow on this instance" <<< "$ERR" && pass "Read block offers always-allow option" || fail "Read block missing always-allow option"
grep -q "Cancel" <<< "$ERR" && pass "Read block offers cancel option" || fail "Read block missing cancel option"
grep -q "Do not retry" <<< "$ERR" && pass "Read block warns against retry" || fail "Read block missing do-not-retry warning"

# --- 2. Edit + Write also blocked with same message shape ---
for TOOL in Edit Write; do
  OUT=$(run_hook "{\"tool_name\":\"$TOOL\",\"tool_input\":{\"file_path\":\"/Users/someone/Downloads/x.txt\"}}")
  RC="${OUT%%|*}"
  ERR="${OUT#*|}"
  [ "$RC" = "2" ] && pass "$TOOL out-of-scope exits 2" || fail "$TOOL out-of-scope exit code" "expected 2, got $RC"
  grep -q "AskUserQuestion" <<< "$ERR" && pass "$TOOL block mentions AskUserQuestion" || fail "$TOOL block missing AskUserQuestion"
done

# --- 3. Glob / Grep out-of-scope path blocks with AskUserQuestion ---
for TOOL in Glob Grep; do
  OUT=$(run_hook "{\"tool_name\":\"$TOOL\",\"tool_input\":{\"path\":\"/Users/someone/Downloads\"}}")
  RC="${OUT%%|*}"
  ERR="${OUT#*|}"
  [ "$RC" = "2" ] && pass "$TOOL out-of-scope exits 2" || fail "$TOOL out-of-scope exit code" "expected 2, got $RC"
  grep -q "AskUserQuestion" <<< "$ERR" && pass "$TOOL block mentions AskUserQuestion" || fail "$TOOL block missing AskUserQuestion"
done

# --- 4. Bash referencing another instance's path is a HARD block ---
# The hard tier has no consent path, so it must NOT invite AskUserQuestion.
OUT=$(run_hook '{"tool_name":"Bash","tool_input":{"command":"cat /tmp/egregore-other-instance/secret.txt"}}')
RC="${OUT%%|*}"
ERR="${OUT#*|}"
[ "$RC" = "2" ] && pass "Bash denied-path exits 2" || fail "Bash denied-path exit code" "expected 2, got $RC"
grep -q "another Egregore instance" <<< "$ERR" && pass "Bash block names foreign instance" || fail "Bash block missing hard-tier message" "stderr: $ERR"
grep -q "AskUserQuestion" <<< "$ERR" && fail "Bash hard block must not offer AskUserQuestion" "stderr: $ERR" || pass "Bash hard block offers no consent path"

# --- 5. In-scope operations still pass cleanly (exit 0, no stderr) ---
OUT=$(run_hook "{\"tool_name\":\"Read\",\"tool_input\":{\"file_path\":\"$FIXTURE_PROJECT/README.md\"}}")
RC="${OUT%%|*}"
[ "$RC" = "0" ] && pass "Read in-scope project path exits 0" || fail "Read in-scope exit code" "expected 0, got $RC"

OUT=$(run_hook "{\"tool_name\":\"Read\",\"tool_input\":{\"file_path\":\"$FIXTURE_MEMORY/note.md\"}}")
RC="${OUT%%|*}"
[ "$RC" = "0" ] && pass "Read memory path exits 0" || fail "Read memory exit code" "expected 0, got $RC"

OUT=$(run_hook "{\"tool_name\":\"Read\",\"tool_input\":{\"file_path\":\"$FIXTURE_REPO/src/main.ts\"}}")
RC="${OUT%%|*}"
[ "$RC" = "0" ] && pass "Read managed-repo path exits 0" || fail "Read managed-repo exit code" "expected 0, got $RC"

OUT=$(run_hook '{"tool_name":"Read","tool_input":{"file_path":"/tmp/scratch.txt"}}')
RC="${OUT%%|*}"
[ "$RC" = "0" ] && pass "Read /tmp system path exits 0" || fail "Read /tmp exit code" "expected 0, got $RC"

# --- 6. Missing boundary file: recomputed, never fail-open ---
# The hook computes the boundary itself from a sandboxed registry instead of
# allowing everything.
rm -f "$BOUNDARY_FILE"
SANDBOX_HOME="$(mktemp -d)"
mkdir -p "$SANDBOX_HOME/.egregore"
printf '[{"slug":"rival","name":"Rival","path":"/Users/someone-else/rival","org_id":"org-rival"}]\n' > "$SANDBOX_HOME/.egregore/instances.json"
run_sandboxed() {
  local err rc
  err=$(echo "$1" | HOME="$SANDBOX_HOME" "$HOOK" 2>&1 >/dev/null)
  rc=$?
  printf '%s|%s' "$rc" "$err"
}
OUT=$(run_sandboxed '{"tool_name":"Read","tool_input":{"file_path":"/Users/someone-else/rival/secret.txt"}}')
RC="${OUT%%|*}"; ERR="${OUT#*|}"
[ "$RC" = "2" ] && grep -q "another Egregore instance" <<< "$ERR" \
  && pass "Missing boundary file: registered instance still denied" \
  || fail "Missing boundary file let an instance through" "$OUT"
OUT=$(run_sandboxed '{"tool_name":"Read","tool_input":{"file_path":"/Users/someone/Documents/x.txt"}}')
RC="${OUT%%|*}"; ERR="${OUT#*|}"
[ "$RC" = "2" ] && grep -q "Boundary consent needed" <<< "$ERR" \
  && pass "Missing boundary file: outside read still asks for consent" \
  || fail "Missing boundary file skipped the consent gate" "$OUT"
OUT=$(run_sandboxed "{\"tool_name\":\"Read\",\"tool_input\":{\"file_path\":\"$FIXTURE_PROJECT/README.md\"}}")
[ "${OUT%%|*}" = "0" ] && pass "Missing boundary file: project read allowed" || fail "Missing boundary file blocked project read" "$OUT"
rm -rf "$SANDBOX_HOME"

# --- 7. A blocked write offers only options that grant writes ---
# read[] grants reads only, so "Always allow on this instance" cannot unblock a write.
cat > "$BOUNDARY_FILE" <<EOF
{"project_dir": "$FIXTURE_PROJECT", "memory_dir": "$FIXTURE_MEMORY", "managed_repos": [], "denied_paths": []}
EOF
OUT=$(run_hook '{"tool_name":"Write","tool_input":{"file_path":"/Users/someone/Documents/out.txt"}}')
ERR="${OUT#*|}"
grep -q "for this session" <<< "$ERR" && pass "Write block offers the session grant" || fail "Write block missing session grant" "$ERR"
grep -q "Always allow on this instance" <<< "$ERR" && fail "Write block offers a read-only grant" "$ERR" || pass "Write block omits the read-only grant"

# --- Summary ---
echo ""
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
